function perfectpixel_disable_comments_applies( $post_type ) {
	return ! ( 'product' === $post_type && 'no' !== strtolower( trim( '{{keep_product_reviews}}' ) ) );
}

function perfectpixel_disable_comments_support() {
	foreach ( get_post_types() as $post_type ) {
		if ( perfectpixel_disable_comments_applies( $post_type ) && post_type_supports( $post_type, 'comments' ) ) {
			remove_post_type_support( $post_type, 'comments' );
			remove_post_type_support( $post_type, 'trackbacks' );
		}
	}
}

function perfectpixel_disable_comments_closed( $open, $post_id ) {
	return perfectpixel_disable_comments_applies( get_post_type( $post_id ) ) ? false : $open;
}

function perfectpixel_disable_comments_hide_existing( $comments, $post_id ) {
	return perfectpixel_disable_comments_applies( get_post_type( $post_id ) ) ? array() : $comments;
}

function perfectpixel_disable_comments_count( $count, $post_id ) {
	return perfectpixel_disable_comments_applies( get_post_type( $post_id ) ) ? 0 : $count;
}

// WooCommerce has its own "Reviews" screen under Products, so the core screens can go.
function perfectpixel_disable_comments_admin_menu() {
	remove_menu_page( 'edit-comments.php' );
	remove_submenu_page( 'options-general.php', 'options-discussion.php' );
}

function perfectpixel_disable_comments_admin_pages() {
	global $pagenow;
	if ( in_array( $pagenow, array( 'edit-comments.php', 'options-discussion.php' ), true ) && ! wp_doing_ajax() ) {
		wp_safe_redirect( admin_url() );
		exit;
	}
}

function perfectpixel_disable_comments_dashboard() {
	remove_meta_box( 'dashboard_recent_comments', 'dashboard', 'normal' );
}

function perfectpixel_disable_comments_admin_bar( $wp_admin_bar ) {
	$wp_admin_bar->remove_node( 'comments' );
}

function perfectpixel_disable_comments_widget() {
	unregister_widget( 'WP_Widget_Recent_Comments' );
}

function perfectpixel_disable_comments_feed() {
	if ( is_comment_feed() ) {
		wp_safe_redirect( home_url( '/' ), 301 );
		exit;
	}
}

function perfectpixel_disable_comments_rest( $endpoints ) {
	unset( $endpoints['/wp/v2/comments'], $endpoints['/wp/v2/comments/(?P<id>[\d]+)'] );
	return $endpoints;
}

function perfectpixel_disable_comments_xmlrpc( $methods ) {
	unset( $methods['wp.newComment'] );
	return $methods;
}

// Last line of defence against direct posts to wp-comments-post.php.
function perfectpixel_disable_comments_reject( $approved, $commentdata ) {
	$post_id = isset( $commentdata['comment_post_ID'] ) ? (int) $commentdata['comment_post_ID'] : 0;
	if ( $post_id && perfectpixel_disable_comments_applies( get_post_type( $post_id ) ) ) {
		return new WP_Error( 'comments_disabled', __( 'Sorry, comments are closed for this item.' ), 403 );
	}
	return $approved;
}
